#!/usr/bin/env node

import fs from 'node:fs';
import path from 'node:path';

const ROOT_DIR = process.cwd();
const PACKAGE_JSON_PATH = path.join( ROOT_DIR, 'package.json' );
const DOCKERFILE_PATH = path.join( ROOT_DIR, 'Dockerfile' );

const BLOCK_BEGIN =
	'# BEGIN: workspace package manifests (auto-generated by bin/sync-docker-workspace-manifests.mjs)';
const BLOCK_END = '# END: workspace package manifests';

const args = new Set( process.argv.slice( 2 ) );
const isCheckMode = args.has( '--check' );

if ( args.has( '--help' ) ) {
	console.log( 'Usage: node bin/sync-docker-workspace-manifests.mjs [--check]' );
	process.exit( 0 );
}

function fail( message ) {
	console.error( message );
	process.exit( 1 );
}

function escapeRegex( value ) {
	return value.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );
}

function segmentToRegex( segment ) {
	const pattern = '^' + segment.split( '*' ).map( escapeRegex ).join( '.*' ) + '$';
	return new RegExp( pattern );
}

function readJson( filePath ) {
	try {
		return JSON.parse( fs.readFileSync( filePath, 'utf8' ) );
	} catch ( error ) {
		fail( `Failed to read JSON file ${ filePath }: ${ error.message }` );
	}
}

function getWorkspacePatterns( packageJson ) {
	if ( Array.isArray( packageJson.workspaces ) ) {
		return packageJson.workspaces;
	}

	if ( Array.isArray( packageJson.workspaces?.packages ) ) {
		return packageJson.workspaces.packages;
	}

	fail( 'Could not find workspaces.packages in package.json.' );
}

function normalizePattern( pattern ) {
	return pattern
		.replaceAll( '\\', '/' )
		.replace( /^\.\/+/, '' )
		.replace( /\/+$/, '' );
}

function getSubdirectories( parentDir ) {
	try {
		return fs
			.readdirSync( parentDir, { withFileTypes: true } )
			.filter( ( entry ) => entry.isDirectory() )
			.map( ( entry ) => entry.name );
	} catch {
		return [];
	}
}

function expandPatternToDirs( pattern ) {
	const normalizedPattern = normalizePattern( pattern );
	const segments = normalizedPattern.split( '/' ).filter( Boolean );
	let dirs = [ ROOT_DIR ];

	for ( const segment of segments ) {
		const nextDirs = [];

		for ( const dir of dirs ) {
			if ( segment.includes( '*' ) ) {
				const regex = segmentToRegex( segment );
				for ( const child of getSubdirectories( dir ) ) {
					if ( regex.test( child ) ) {
						nextDirs.push( path.join( dir, child ) );
					}
				}
				continue;
			}

			const childDir = path.join( dir, segment );
			try {
				if ( fs.statSync( childDir ).isDirectory() ) {
					nextDirs.push( childDir );
				}
			} catch {
				// Ignore missing directories here; a helpful error is emitted if nothing matches below.
			}
		}

		dirs = nextDirs;
	}

	if ( dirs.length === 0 ) {
		fail( `Workspace pattern "${ pattern }" matched no directories.` );
	}

	return dirs.map( ( dir ) => path.relative( ROOT_DIR, dir ).replaceAll( '\\', '/' ) );
}

function getWorkspaceManifestPaths( workspacePatterns ) {
	const manifestPaths = new Set();

	for ( const pattern of workspacePatterns ) {
		const dirs = expandPatternToDirs( pattern );
		const isWildcardPattern = pattern.includes( '*' );
		let manifestsFoundForPattern = 0;

		for ( const dir of dirs ) {
			const manifestPath = `${ dir }/package.json`;
			const absoluteManifestPath = path.join( ROOT_DIR, manifestPath );

			if ( ! fs.existsSync( absoluteManifestPath ) ) {
				if ( isWildcardPattern ) {
					continue;
				}

				fail( `Expected workspace manifest does not exist: ${ manifestPath }` );
			}

			manifestsFoundForPattern += 1;
			manifestPaths.add( manifestPath );
		}

		if ( manifestsFoundForPattern === 0 ) {
			fail( `Workspace pattern "${ pattern }" did not resolve to any package.json files.` );
		}
	}

	return [ ...manifestPaths ].sort();
}

function buildDockerCopyLines( manifestPaths ) {
	if ( manifestPaths.length === 0 ) {
		fail( 'No workspace package.json files found to generate Docker COPY block.' );
	}

	return [
		'COPY --parents \\',
		...manifestPaths.map( ( manifestPath ) => `  ./${ manifestPath } \\` ),
		'  /calypso/',
	];
}

function findBlockRange( lines ) {
	const beginIndex = lines.findIndex( ( line ) => line.trim() === BLOCK_BEGIN );
	const endIndex = lines.findIndex( ( line ) => line.trim() === BLOCK_END );

	if ( beginIndex === -1 || endIndex === -1 || endIndex <= beginIndex ) {
		fail(
			`Could not find a valid managed block in Dockerfile. Expected markers:\n${ BLOCK_BEGIN }\n${ BLOCK_END }`
		);
	}

	return { beginIndex, endIndex };
}

function updateDockerfile( copyLines ) {
	const dockerfileContent = fs.readFileSync( DOCKERFILE_PATH, 'utf8' );
	const lines = dockerfileContent.split( /\r?\n/ );
	const { beginIndex, endIndex } = findBlockRange( lines );

	const nextLines = [
		...lines.slice( 0, beginIndex + 1 ),
		...copyLines,
		...lines.slice( endIndex ),
	];

	const currentManagedLines = lines.slice( beginIndex + 1, endIndex );
	const isUpToDate =
		currentManagedLines.length === copyLines.length &&
		currentManagedLines.every( ( line, index ) => line === copyLines[ index ] );

	if ( isCheckMode ) {
		if ( ! isUpToDate ) {
			fail(
				'Docker workspace manifest COPY block is out of date. Run: yarn run sync:docker-workspace-manifests'
			);
		}

		console.log( 'Docker workspace manifest COPY block is up to date.' );
		return;
	}

	if ( isUpToDate ) {
		console.log( 'Docker workspace manifest COPY block is already up to date.' );
		return;
	}

	fs.writeFileSync( DOCKERFILE_PATH, nextLines.join( '\n' ) );
	console.log( `Updated Docker workspace manifest COPY block with ${ copyLines.length } entries.` );
}

const packageJson = readJson( PACKAGE_JSON_PATH );
const workspacePatterns = getWorkspacePatterns( packageJson );
const manifestPaths = getWorkspaceManifestPaths( workspacePatterns );
const copyLines = buildDockerCopyLines( manifestPaths );

updateDockerfile( copyLines );
